//! Noise fixtures generated by the pinned original renderer.
use filmcraft_project::{Param,ParamValue};
use filmcraft_render::{effects::{apply,FxCtx},image::Image};
use serde_json::json;
fn main(){
 let mut cases=vec![];
 for (w,h) in [(1,7),(7,1),(6,4),(18,10)] {for local_tick in [0u64,33333,33334,99999,100000,500000] {for (amount,grain_size,color,clip) in [(25.0,1.0,true,true),(100.0,2.5,false,false),(0.0,10.0,true,true),(100.0,10.0,true,false)] {
  let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();
  let input:Vec<[f32;4]>=rgba.chunks_exact(4).map(|p|{let a=p[3] as f32/255.0;[filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[1] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[2] as f32/255.0)*a,a]}).collect();
  let mut image=Image{w,h,px:input.iter().flatten().copied().collect()};
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="noise").unwrap().instance();
  effect.params.insert("amount".into(),Param::new(ParamValue::Float(amount)));
  effect.params.insert("grain_size".into(),Param::new(ParamValue::Float(grain_size)));
  effect.params.insert("color".into(),Param::new(ParamValue::Bool(color)));
  effect.params.insert("clip".into(),Param::new(ParamValue::Bool(clip)));
  let cx=FxCtx{t:filmcraft_time::Tick(local_tick as i64),px_scale:1.0,seconds:local_tick as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  cases.push(json!({"localTick":local_tick,"parameters":{"amount":amount,"grainSize":grain_size,"color":color,"clip":clip},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
 }}}
 let mut browser=Image{w:160,h:90,px:[0.25f32,0.5,0.75,1.0].repeat(160*90)};
 let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="noise").unwrap().instance();
 effect.params.insert("amount".into(),Param::new(ParamValue::Float(25.0)));
 effect.params.insert("grain_size".into(),Param::new(ParamValue::Float(2.0)));
 effect.params.insert("color".into(),Param::new(ParamValue::Bool(false)));
 effect.params.insert("clip".into(),Param::new(ParamValue::Bool(false)));
 let cx=FxCtx{t:filmcraft_time::Tick(500000),px_scale:1.0,seconds:0.5,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
 apply(&mut browser,&effect,&cx);
 let mut media=vec![];
 for tick in [0u64,250000,500000] {
  let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12 {255}else{32};[v,v,v,128]}).collect();
  let input:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;let v=filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a;[v,v,v,a]}).collect();
  let mut image=Image{w:16,h:16,px:input};
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="noise").unwrap().instance();
  effect.params.insert("amount".into(),Param::new(ParamValue::Float(25.0+tick as f64/500000.0*50.0)));
  effect.params.insert("grain_size".into(),Param::new(ParamValue::Float(1.0+tick as f64/500000.0*3.0)));
  effect.params.insert("color".into(),Param::new(ParamValue::Bool(true)));
  effect.params.insert("clip".into(),Param::new(ParamValue::Bool(false)));
  let cx=FxCtx{t:filmcraft_time::Tick(tick as i64),px_scale:1.0,seconds:tick as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  let mut frames=vec![];
  for index in 0..(1000000-tick).div_ceil(100000) {
   let clock=tick+index*100000;
   let local=clock.min(500000);
   effect.params.insert("amount".into(),Param::new(ParamValue::Float(25.0+local as f64/500000.0*50.0)));
  effect.params.insert("grain_size".into(),Param::new(ParamValue::Float(1.0+local as f64/500000.0*3.0)));
  effect.params.insert("color".into(),Param::new(ParamValue::Bool(true)));
  effect.params.insert("clip".into(),Param::new(ParamValue::Bool(false)));
   let px:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;let v=filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a;[v,v,v,a]}).collect();
   let mut frame=Image{w:16,h:16,px};
   let cx=FxCtx{t:filmcraft_time::Tick(clock as i64),px_scale:1.0,seconds:clock as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
   apply(&mut frame,&effect,&cx);
   frames.push(frame.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());
  }
  media.push(json!({"localTick":tick,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),"frames":frames}));
 }
 println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media,"browser":{"localTick":500000,"rgba":browser.to_rgba8()}}));
}
